```yaml
name: Workflows Approval

on:
  pull_request_target:
    types:
      - labeled
      - synchronize
    branches:
      - main
      - release-**

permissions:
  contents: read

jobs:
  approve-workflows:
    runs-on: ubuntu-latest
    permissions:
      actions: write
    steps:
      - name: Check if contributor is first-time
        id: check_contributor
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.number;
            const author = context.payload.pull_request.user.login;

            // Get all PRs by this author
            const prsQuery = `
              query($owner: String!, $repo: String!, $author: String!) {
                repository(owner: $owner, name: $repo) {
                  pullRequests(first: 100, states: OPEN, orderBy: {field: CREATED_AT, direction: ASC}, filterBy: {author: $author}) {
                    nodes {
                      number
                    }
                  }
                }
              }
            `;

            const result = await github.graphql(prsQuery, {
              owner: owner,
              repo: repo,
              author: author
            });

            const prCount = result.repository.pullRequests.nodes.length;
            const isFirstTime = prCount <= 1;

            console.log(`Contributor ${author} has opened ${prCount} PR(s). Is first-time: ${isFirstTime}`);

            // If contributor is first-time, check for ok-to-test label
            if (isFirstTime) {
              const labelsQuery = `
                query($owner: String!, $repo: String!, $prNumber: Int!) {
                  repository(owner: $owner, name: $repo) {
                    pullRequest(number: $prNumber) {
                      labels(first: 100) {
                        nodes {
                          name
                        }
                      }
                    }
                  }
                }
              `;

              const labelsResult = await github.graphql(labelsQuery, {
                owner: owner,
                repo: repo,
                prNumber: prNumber
              });

              const labels = labelsResult.repository.pullRequest.labels.nodes.map(label => label.name);
              const hasOkToTest = labels.includes('ok-to-test');

              console.log(`PR ${prNumber} has ok-to-test label: ${hasOkToTest}`);

              if (hasOkToTest) {
                console.log("Approving workflows for first-time contributor with ok-to-test label");
                core.setOutput('should_approve', 'true');
              } else {
                console.log("First-time contributor without ok-to-test label - no approval needed");
                core.setOutput('should_approve', 'false');
              }
            } else {
              console.log("Returning contributor - auto-approving workflows");
              core.setOutput('should_approve', 'true');
            }

      - name: Approve workflows
        if: steps.check_contributor.outputs.should_approve == 'true'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.number;

            // Get all workflow runs for this PR
            const runsQuery = `
              query($owner: String!, $repo: String!, $prNumber: Int!) {
                repository(owner: $owner, name: $repo) {
                  pullRequest(number: $prNumber) {
                    latestGraphQlRef: headRef {
                      name
                    }
                    latestGraphQlRefOid: headRefOid
                    baseRef {
                      name
                    }
                    baseRefOid: target {
                      oid
                    }
                    headRef {
                      name
                    }
                    headRefOid: target {
                      oid
                    }
                    commits(last: 1) {
                      nodes {
                        commit {
                          oid
                        }
                      }
                    }
                    statusCheckRollup {
                      contexts(first: 100) {
                        nodes {
                          __typename
                          ... on StatusContext {
                            id
                            context
                            state
                            conclusion
                            targetUrl
                          }
                        }
                      }
                    }
                  }
                }
              }
            `;

            const runsResult = await github.graphql(runsQuery, {
              owner: owner,
              repo: repo,
              prNumber: prNumber
            });

            // Get workflow runs for the PR branch
            const workflowRuns = await github.rest.actions.listWorkflowRunsForRepo({
              owner: owner,
              repo: repo,
              head_sha: runsResult.repository.pullRequest.headRefOid,
              per_page: 100
            });

            // Filter for pending workflow runs
            const pendingRuns = workflowRuns.data.workflow_runs.filter(run => 
              run.status === 'queued' || run.status === 'in_progress'
            );

            // Approve each pending workflow run
            for (const run of pendingRuns) {
              try {
                await github.rest.actions.approveWorkflowRun({
                  owner: owner,
                  repo: repo,
                  run_id: run.id
                });
                console.log(`Approved workflow run ${run.id}`);
              } catch (error) {
                console.error(`Failed to approve workflow run ${run.id}:`, error.message);
              }
            }
